<?php require 'config.php'; require_admin(); $msg=''; if(isset($_POST['add'])){$roll=trim($_POST['roll_no']);$name=trim($_POST['name']);$class=trim($_POST['class_name']);$email=trim($_POST['email']);$s=$conn->prepare('INSERT INTO students (roll_no,name,class_name,email) VALUES (?,?,?,?)');$s->bind_param('ssss',$roll,$name,$class,$email);$msg=$s->execute()?'Student added successfully.':'Could not add student. Roll number may already exist.';} if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$conn->query("DELETE FROM students WHERE id=$id");header('Location: students.php');exit;} $students=$conn->query('SELECT * FROM students ORDER BY id DESC');$page_title='Manage Students'; require 'header.php'; ?>
<div class="page-head"><h1>Students</h1><p>Add and maintain student records.</p></div><div class="two-col"><form class="panel" method="post"><h2>Add Student</h2><?php if($msg):?><p class="alert"><?=e($msg)?></p><?php endif;?><label>Roll Number</label><input name="roll_no" required><label>Student Name</label><input name="name" required><label>Class / Course</label><input name="class_name" required><label>Email (optional)</label><input type="email" name="email"><button name="add">Add Student</button></form><div class="panel table-wrap"><h2>All Students</h2><table><tr><th>Roll No.</th><th>Name</th><th>Class</th><th></th></tr><?php while($s=$students->fetch_assoc()):?><tr><td><?=e($s['roll_no'])?></td><td><?=e($s['name'])?></td><td><?=e($s['class_name'])?></td><td><a class="danger" onclick="return confirm('Delete this student?')" href="?delete=<?=$s['id']?>">Delete</a></td></tr><?php endwhile;?></table></div></div>
<?php require 'footer.php'; ?>
